#pragma once
#include <Arduino.h>
namespace MusicWeb {
template <typename Page> inline void append(Page &page) {
  page += F(R"HTML(<section class='panel' data-panel='music' hidden><h2>音乐与歌词</h2><p class='intro'>上传完整歌曲和 LRC，选择云端歌单。播放时仍可唤醒助手。</p>
<div class='card'><h3 id='full-music-title'>尚未播放</h3><p id='full-music-artist'></p><p id='full-music-state' role='status'></p><progress id='full-music-progress' max='100' value='0' style='width:100%'></progress><p id='full-music-time'></p><p id='full-music-lyric' style='font-size:21px;white-space:pre-wrap'></p><p id='full-music-next-lyric' class='meta' style='white-space:pre-wrap'></p>
<div class='actions'><button data-full-music-action='previous'>上一首</button><button data-full-music-action='pause'>暂停</button><button data-full-music-action='resume'>继续</button><button data-full-music-action='next'>下一首</button><button data-full-music-action='stop' class='secondary'>停止</button></div><label for='full-music-volume'>音量（与语音共用）</label><input id='full-music-volume' type='range' min='0' max='100' value='35'></div>
<div class='card'><label for='full-music-query'>歌曲或歌手</label><input id='full-music-query' placeholder='输入歌曲名或歌手'><div class='actions'><button id='full-music-search'>搜索</button><button id='full-music-search-play'>搜索并播放</button><button id='full-music-library'>全部歌曲</button></div><p id='full-music-message' role='status'></p><div id='full-music-tracks'></div><button id='full-music-more' hidden>更多歌曲</button></div>
<div class='card'><h3>服务器歌单</h3><label for='full-music-playlist'>播放队列</label><select id='full-music-playlist'><option value=''>全部歌曲</option></select><div class='actions'><button id='full-music-playlist-refresh'>刷新歌单</button><button id='full-music-playlist-show'>查看歌单</button><button id='full-music-playlist-delete' class='danger'>删除当前歌单</button></div><input id='full-music-playlist-title' placeholder='新歌单名称'><button id='full-music-playlist-create'>创建歌单</button></div>
<div class='card'><h3>上传音乐与 LRC</h3><p class='meta'>完整 MP3 / WAV 直接传云端，容量由剩余空间决定。歌名、歌手留空可自动识别；可补歌词到自己的歌曲。</p><label for='full-music-upload-track'>上传目标</label><select id='full-music-upload-track'><option value=''>新增歌曲</option></select><label for='full-music-audio'>音乐文件</label><input id='full-music-audio' type='file' accept='audio/mpeg,audio/wav,.mp3,.wav'><label for='full-music-lrc'>歌词文件（可选）</label><input id='full-music-lrc' type='file' accept='.lrc,text/plain'><label for='full-music-upload-title'>歌名</label><input id='full-music-upload-title'><label for='full-music-upload-artist'>歌手</label><input id='full-music-upload-artist'><div class='actions'><button id='full-music-upload'>上传</button><button id='full-music-upload-cancel' class='secondary' disabled>取消上传</button></div><progress id='full-music-upload-progress' max='100' value='0' style='width:100%'></progress><p id='full-music-upload-status' role='status'></p></div></section>
<script>(()=>{const $=id=>document.getElementById(id);let cursor=null,query='',listMode=false,listCursor=null,xhr=null,volumeTouched=false;
const message=text=>{$('full-music-message').textContent=text;};
async function api(path,method='GET',data=null){const r=await adminFetch('/music/cloud',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path,method,data})});if(!r.ok)throw new Error(await r.text());return r.status===204?{}:await r.json();}
async function control(action,value=''){const r=await adminFetch('/music/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,value})});if(!r.ok)throw new Error(await r.text());await status();}
const run=fn=>async()=>{try{await fn();}catch(e){message(e.message);}};
const minute=ms=>Math.floor((ms||0)/60000)+':'+String(Math.floor((ms||0)/1000)%60).padStart(2,'0');
async function status(){const r=await adminFetch('/music/status');if(!r.ok)return;const d=await r.json();$('full-music-title').textContent=d.title||'尚未播放';$('full-music-artist').textContent=d.artist||'';const states={playing:'播放中',buffering:'正在缓冲',paused:'已暂停',suspended:'助手处理任务中',stopped:'已停止',error:'播放失败',unavailable:'播放器未就绪'};$('full-music-state').textContent=(states[d.state]||d.state)+(d.error?' · '+d.error:'');$('full-music-lyric').textContent=d.lyric||'';$('full-music-next-lyric').textContent=d.next_lyric||'';$('full-music-time').textContent=minute(d.position_ms)+' / '+minute(d.duration_ms)+'（预计）';$('full-music-progress').value=d.duration_ms?Math.min(100,d.position_ms*100/d.duration_ms):0;if(!volumeTouched)$('full-music-volume').value=d.volume||0;}
function button(label,fn,danger=false){const b=document.createElement('button');b.type='button';b.textContent=label;if(danger)b.className='danger';b.onclick=run(fn);return b;}
function uploadMode(){const attach=!!$('full-music-upload-track').value,audio=$('full-music-audio'),title=$('full-music-upload-title'),artist=$('full-music-upload-artist');if(attach)audio.value='';else if(title.disabled){title.value='';artist.value='';}audio.disabled=attach;title.disabled=attach;artist.disabled=attach;}
function render(tracks,append=false,playlistView=false){
if(!append){$('full-music-tracks').replaceChildren();$('full-music-upload-track').replaceChildren(new Option('新增歌曲',''));uploadMode();}
for(const track of tracks){const own=!!track.owner,row=document.createElement('div');row.className='alarm-row';const name=document.createElement('p');name.textContent=track.title+(track.artist?' · '+track.artist:'')+' · '+minute(track.duration_ms)+(track.lyrics_available?' · 有歌词':'')+(own?' · 我的音乐':' · 共享音乐');row.append(name);const actions=document.createElement('div');actions.className='actions';actions.append(button('播放',()=>control('play',track.id)));
if(own)actions.append(button('补歌词',()=>{$('full-music-upload-track').value=track.id;$('full-music-upload-title').value=track.title;$('full-music-upload-artist').value=track.artist||'';uploadMode();$('full-music-lrc').focus();}));
actions.append(button('加入歌单',async()=>{const id=$('full-music-playlist').value;if(!id)throw new Error('先选择一个歌单');await api('/music/playlists/'+encodeURIComponent(id)+'/tracks','POST',{track_id:track.id});message('已加入歌单');}));
if(playlistView)actions.append(button('移出歌单',async()=>{await api('/music/playlists/'+encodeURIComponent($('full-music-playlist').value)+'/tracks/'+encodeURIComponent(track.id),'DELETE');row.remove();}));
if(own){actions.append(button('删除歌曲',async()=>{if(!confirm('删除歌曲“'+track.title+'”？'))return;await api('/music/'+encodeURIComponent(track.id),'DELETE');row.remove();},true));$('full-music-upload-track').add(new Option(track.title+(track.artist?' · '+track.artist:''),track.id));}
row.append(actions);$('full-music-tracks').append(row);}}
async function library(append=false){listMode=false;const d=await api('/music?q='+encodeURIComponent(query)+'&cursor='+(append?cursor||0:0)+'&limit=20');cursor=d.next_cursor;render(d.tracks||[],append);$('full-music-more').hidden=cursor==null;message((d.tracks||[]).length?'':'没有匹配歌曲');}
async function playlists(){const selected=$('full-music-playlist').value,d=await api('/music/playlists');$('full-music-playlist').replaceChildren(new Option('全部歌曲',''));for(const p of d.playlists||[])$('full-music-playlist').add(new Option(p.title+'（'+p.count+'）',p.id));$('full-music-playlist').value=selected;}
async function showPlaylist(append=false){const id=$('full-music-playlist').value;if(!id){query='';return library();}listMode=true;const d=await api('/music/playlists/'+encodeURIComponent(id)+'?cursor='+(append?listCursor||0:0)+'&limit=20');listCursor=d.next_cursor;render(d.tracks||[],append,true);$('full-music-more').hidden=listCursor==null;}
document.querySelectorAll('[data-full-music-action]').forEach(b=>b.onclick=run(()=>control(b.dataset.fullMusicAction)));
$('full-music-search').onclick=run(()=>{query=$('full-music-query').value.trim();return library();});$('full-music-search-play').onclick=run(()=>control('search',$('full-music-query').value.trim()));$('full-music-library').onclick=run(()=>{query='';return library();});$('full-music-more').onclick=run(()=>listMode?showPlaylist(true):library(true));
$('full-music-playlist').onchange=run(()=>control('playlist',$('full-music-playlist').value));$('full-music-playlist-refresh').onclick=run(playlists);$('full-music-playlist-show').onclick=run(()=>showPlaylist());$('full-music-playlist-create').onclick=run(async()=>{const title=$('full-music-playlist-title').value.trim();if(!title)throw new Error('填写歌单名');await api('/music/playlists','POST',{title});$('full-music-playlist-title').value='';await playlists();});$('full-music-playlist-delete').onclick=run(async()=>{const id=$('full-music-playlist').value;if(!id||!confirm('删除当前歌单？'))return;await api('/music/playlists/'+encodeURIComponent(id),'DELETE');await control('playlist','');await playlists();});
$('full-music-volume').oninput=()=>{volumeTouched=true;};$('full-music-volume').onchange=run(async()=>{await control('volume',$('full-music-volume').value);volumeTouched=false;});
$('full-music-audio').onchange=()=>{$('full-music-upload-title').placeholder='留空时自动读取歌曲标签或文件名';};
$('full-music-upload-track').onchange=uploadMode;
$('full-music-upload').onclick=async()=>{const track=$('full-music-upload-track').value,audio=track?null:$('full-music-audio').files[0],lyrics=$('full-music-lrc').files[0],s=$('full-music-upload-status');if(!track&&!audio){s.textContent='请选择音乐文件';return;}if(track&&!lyrics){s.textContent='请选择歌词文件';return;}if(lyrics&&lyrics.size>1024*1024){s.textContent='歌词不能超过 1 MB';return;}$('full-music-upload').disabled=true;try{const r=await adminFetch('/music/upload-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({origin:window.location.origin,...(track?{track_id:track}:{})})});if(!r.ok)throw new Error(await r.text());const ticket=await r.json(),form=new FormData();if(audio)form.append('audio',audio);if(lyrics)form.append('lyrics',lyrics);if(track)form.append('track_id',track);else{form.append('title',$('full-music-upload-title').value);form.append('artist',$('full-music-upload-artist').value);}xhr=new XMLHttpRequest();xhr.open('POST',ticket.url);xhr.setRequestHeader('X-Music-Upload-Token',ticket.token);xhr.upload.onprogress=e=>{$('full-music-upload-progress').value=e.lengthComputable?e.loaded*100/e.total:0;s.textContent=e.lengthComputable?'上传 '+Math.round(e.loaded*100/e.total)+'%':'正在上传';};$('full-music-upload-cancel').disabled=false;s.textContent='正在上传到云端';await new Promise((resolve,reject)=>{xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(new Error(xhr.responseText||'上传失败'));xhr.onerror=()=>reject(new Error('上传网络失败'));xhr.onabort=()=>reject(new Error('上传已取消'));xhr.send(form);});s.textContent='上传完成';$('full-music-audio').value='';$('full-music-lrc').value='';query='';await library();}catch(e){s.textContent=e.message;}finally{xhr=null;$('full-music-upload').disabled=false;$('full-music-upload-cancel').disabled=true;}};
$('full-music-upload-cancel').onclick=()=>xhr?.abort();let initialized=false;async function refresh(){if(document.querySelector('[data-panel="music"]').hidden)return;try{await status();if(!initialized){initialized=true;await playlists();await library();}}catch(e){message(e.message);}}setInterval(refresh,1500);window.addEventListener('hashchange',refresh);refresh();})();</script>)HTML");
}
}
